// National Emblem of India (Lion Capital of Ashoka - Satyameva Jayate)
// Base64 encoded PNG for reliable embedding in PDF test reports
export const NATIONAL_EMBLEM_PNG_BASE64 = "";

export function getNationalEmblemBytes(): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return Buffer.from(NATIONAL_EMBLEM_PNG_BASE64, "base64");
  }
  const binaryString = atob(NATIONAL_EMBLEM_PNG_BASE64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}
